  await page.locator('#question').fill('How can cities make streets cooler in summer?');await page.locator('#question').press('Enter');await page.locator('.citation').first.wait_for();check('citation available during active stream',await page.locator('#stop').is_visible());await shot(page,'01-citation-during-stream.png')
  await page.locator('#question').fill('A draft that remains\nwhile I read a source')
